```java
// ─── File: src/main/java/com/bank/core/Account.java ───
package com.bank.core;

import java.io.*;
import java.math.BigDecimal;

public class Account implements Externalizable {
    private static final long serialVersionUID = 1L;

    private String accountId;
    private String holderName;
    private BigDecimal balance;

    // MANDATORY public no-arg constructor — the engine calls it before readExternal.
    public Account() { }

    public Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
    }

    // Full manual control: YOU choose fields and order.
    @Override
    public void writeExternal(ObjectOutput out) throws IOException {
        out.writeUTF(accountId);
        out.writeUTF(holderName);
        out.writeUTF(balance.toPlainString());
    }

    // Must read in the SAME order as written.
    @Override
    public void readExternal(ObjectInput in) throws IOException, ClassNotFoundException {
        this.accountId = in.readUTF();
        this.holderName = in.readUTF();
        this.balance = new BigDecimal(in.readUTF());
    }

    public String getAccountId() { return accountId; }
    public String getHolderName() { return holderName; }
    public BigDecimal getBalance() { return balance; }
}
```

