// ─── File: src/main/java/com/bank/core/ExternalizableDemo.java ───
package com.bank.core;

import java.io.*;
import java.math.BigDecimal;
import java.util.logging.*;

public class ExternalizableDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));

        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        try (ObjectOutputStream oos = new ObjectOutputStream(buffer)) {
            oos.writeObject(rajesh); // triggers writeExternal
        }
        byte[] bytes = buffer.toByteArray();
        log.info(() -> "Externalized bytes = " + bytes.length + " (hand-controlled format)");

        Account back;
        try (ObjectInputStream ois =
                 new ObjectInputStream(new ByteArrayInputStream(bytes))) {
            // Engine: new Account() via no-arg ctor, THEN readExternal.
            back = (Account) ois.readObject();
        }
        log.info(() -> "Rebuilt: " + back.getAccountId() + " / " + back.getHolderName()
                        + " balance=" + back.getBalance());
    }
}
```
